package com.foodie.order;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;
@Component class RemoteClients{private final RestClient users,food;RemoteClients(RestClient.Builder b){users=b.baseUrl("http://user-service").build();food=b.baseUrl("http://food-service").build();}record User(Long customerId,String name,String email,String phone,String address){}record Dish(Long dishId,Long restaurantId,String name,String description,BigDecimal price,String category){}void requireUser(Long id){fetch(users,"/api/users/"+id,User.class,"User");}Dish dish(Long id){return fetch(food,"/api/dishes/"+id,Dish.class,"Dish");}private <T>T fetch(RestClient c,String uri,Class<T> type,String name){try{return c.get().uri(uri).retrieve().body(type);}catch(HttpClientErrorException.NotFound e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,name+" not found");}catch(RestClientException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Dependent service unavailable");}}}
